    expired: { reply: ["¿Lo pudiste ver?", "Le voy a decir a mi papá que lo revise contigo."], outcome: "Diego fue directo con su papá. La decisión se te está saliendo de las manos.", effects: { consejo: -4 } },
    lesson: "innovacion",
