    options: [
      { id: "a", stance: {mariana: 2, hector: -2}, text: "Aplicar la política: baja con respeto y en privado, sin exhibirlo, recuperando el monto. Yo mismo explico al equipo comercial que aquí la integridad no depende de cuánto vendes.", reply: ["(Mariana) Entendido. Lo hacemos mañana a primera hora, con cuidado.", "(Una semana después) Dos vendedores me dijeron en confianza que ya era hora. Uno me contó que él siempre se sintió tonto por reportar sus gastos exactos."], outcome: "Pierdes ventas a corto plazo. Ganas algo más difícil de construir: que la regla sea igual para todos.", effects: { equipo: 5, consejo: 3, clientes: -4 }, style: { conflicto: 2, horizonte: 2, foco: -1 }, score: 3 },
      { id: "b", stance: {hector: 1, mariana: -2}, text: "Darle una segunda oportunidad en privado: que devuelva el dinero, firme un acta y no se habla más del tema.", reply: ["(Mariana) Lo hago así.", "(Un mes después) Ya se sabe en todo el equipo. Me preguntan si la política aplica para todos o nada más para los que venden poco."], outcome: "Proteges las ventas de Fernando y le enseñas a toda la empresa que la ética tiene precio.", effects: { clientes: 1, margen: 2, equipo: -6, consejo: -2 }, style: { conflicto: -2, foco: -1, horizonte: -2 }, score: 0 },
      { id: "c", stance: {mariana: -1, hector: 1}, text: "Que lo decida su jefe directo en Comercial. Es su equipo.", reply: ["(Mariana) Ok, le paso el expediente.", "(Comercial le da una amonestación verbal.)"], outcome: "Evitaste la decisión. Su jefe conserva a su mejor vendedor, y la cultura la decidió alguien más por ti.", effects: { clientes: 2, equipo: -3, consejo: -1 }, style: { conflicto: -2, estilo: 1 }, score: 1 },
    ],
    expired: { reply: ["(Mariana) Como no hubo instrucción, el caso se quedó archivado."], outcome: "Archivar también comunica.", effects: { equipo: -5 } },
    lesson: "cultura",
